/** One actor card. Generated by scripts/import-tmdb.mjs into public/data/*.json. */
export type Character = {
  id: string;
  name: string;
  /** "Known for …" line under the card. */
  subtitle: string;
  /** Shown when the photo is missing. */
  initials: string;
  /** Background behind the photo / initials. */
  color: string;
  /** From the actor's TMDB person record (the importer stores only female/male). */
  attributes?: {
    gender?: "WOMAN" | "MAN";
  };
  /** Shown in the actor details panel and used by the filters. */
  details?: {
    birthday?: string; // YYYY-MM-DD
    deathday?: string; // YYYY-MM-DD
    placeOfBirth?: string;
    bio?: string;
    knownFor?: string[];
  };
  tmdb: {
    personId: number;
    profilePath?: string;
  };
};
